create table public.equipe_padrao (
  id bigserial primary key, obra_id text not null, tipo text not null, nome text not null, composicao text not null,
  pessoas int not null check (pessoas > 0), unique (obra_id, tipo));
create table public.indice_produtividade (
  id bigserial primary key, obra_id text not null, orcamento_id bigint not null, codigo_eap text not null, pavimento text,
  unidade text, regra text not null default 'indice' check (regra in ('indice', 'duracao')),
  hh_por_unidade numeric(14,6), horas_total numeric(12,4), origem text check (origem in ('rafael', 'cronograma', 'cpu_flats', '')),
  hh_cronograma numeric(14,6), conferir boolean not null default false, tipo_equipe text, observacao text,
  atualizado_em timestamptz not null default now(), unique (obra_id, orcamento_id));
create table public.insumo_prazo_entrega (
  id bigserial primary key, obra_id text not null, orcamento_id bigint not null, codigo_eap text not null, pavimento text,
  categoria text not null, regra text not null check (regra in ('antecedencia', 'ultimo_mes')),
  antecedencia_dias int check (antecedencia_dias >= 0), observacao text, atualizado_em timestamptz not null default now(),
  unique (obra_id, orcamento_id));
create table public.obra_jornada (
  obra_id text primary key, horas_dia numeric(4,2) not null check (horas_dia > 0 and horas_dia <= 24),
  dias_semana int[] not null, observacao text);
create table public.obra_feriados (
  id bigserial primary key, obra_id text not null, data date not null, descricao text not null,
  abrangencia text not null check (abrangencia in ('nacional', 'estadual', 'municipal')), unique (obra_id, data));
alter table public.equipe_padrao enable row level security;
revoke all on public.equipe_padrao from anon, authenticated;
alter table public.indice_produtividade enable row level security;
revoke all on public.indice_produtividade from anon, authenticated;
alter table public.insumo_prazo_entrega enable row level security;
revoke all on public.insumo_prazo_entrega from anon, authenticated;
alter table public.obra_jornada enable row level security;
revoke all on public.obra_jornada from anon, authenticated;
alter table public.obra_feriados enable row level security;
revoke all on public.obra_feriados from anon, authenticated;
revoke all on sequence public.equipe_padrao_id_seq from anon, authenticated;
revoke all on sequence public.indice_produtividade_id_seq from anon, authenticated;
revoke all on sequence public.insumo_prazo_entrega_id_seq from anon, authenticated;
revoke all on sequence public.obra_feriados_id_seq from anon, authenticated;

