do $$
begin
  if (select count(*) from public.equipe_padrao where obra_id = 'sirius60') <> 13
     or (select count(*) from public.indice_produtividade where obra_id = 'sirius60') <> 269
     or (select count(*) from public.insumo_prazo_entrega where obra_id = 'sirius60') <> 82
     or (select count(*) from public.obra_feriados where obra_id = 'sirius60') <> 24 then
    raise exception 'carga com quantidade diferente do esperado: nada foi gravado';
  end if;
  if exists (select 1 from public.indice_produtividade i where i.obra_id = 'sirius60' and i.tipo_equipe <> ''
              and not exists (select 1 from public.equipe_padrao e where e.obra_id = 'sirius60' and e.tipo = i.tipo_equipe)) then
    raise exception 'índice com tipo de equipe sem cadastro: nada foi gravado';
  end if;
end $$;

