-- Conferência: índices por origem e linhas pendentes
select coalesce(nullif(origem, ''), 'PENDENTE') as origem, count(*) as linhas, count(*) filter (where conferir) as conferir,
       count(*) filter (where coalesce(tipo_equipe, '') = '') as sem_equipe
  from public.indice_produtividade where obra_id = 'sirius60' group by 1 order by 1;
